const copy=value=>JSON.parse(JSON.stringify(value));
function equal(a,b){if(a===b)return true;if(a===null||b===null||typeof a!=='object'||typeof b!=='object')return false;const ak=Object.keys(a).sort(),bk=Object.keys(b).sort();return ak.length===bk.length&&ak.every((k,i)=>k===bk[i]&&equal(a[k],b[k]))}
function diffLayouts(before,after){let ops=[];for(const collection of ['items','decorations']){const a=new Map(before[collection].map(x=>[x.id,x])),b=new Map(after[collection].map(x=>[x.id,x]));for(const id of new Set([...a.keys(),...b.keys()])){const old=a.get(id)||null,next=b.get(id)||null;if(!equal(old,next))ops.push({collection,id,before:old,after:next})}}return ops}
function mergePatch(layout,ops){const next=copy(layout),conflicts=[];for(const op of ops){const list=next[op.collection],index=list.findIndex(x=>x.id===op.id),value=index<0?null:list[index];if(equal(value,op.after))continue;if(!equal(value,op.before)){conflicts.push(op);continue}if(op.after===null){if(index>=0)list.splice(index,1)}else if(index>=0)list[index]=copy(op.after);else list.push(copy(op.after))}return {layout:next,conflicts}}

