const PIDS=new Set(['kivik','lack','lisabo','chair','kallax','poang','lo hals','hektar','malm']);
const KEY='global-layout/v1.json',MAX_BYTES=450000;
export function initialLayout(){const colors={kivik:'#c4bfad',lack:'#615346','lo hals':'#bda984',lisabo:'#cfb389',chair:'#bf9e73'};return {version:2,items:[['kivik',4200,5700,270],['lack',2500,5700,90],['lo hals',2550,5700,0],['lisabo',1550,2250,90],['chair',900,1950,270],['chair',900,2600,270],['chair',2200,1950,90],['chair',2200,2600,90]].map(([pid,x,y,r],i)=>({id:'shared-default-'+i,pid,x,y,r,color:colors[pid]})),decorations:[]}}
const ID=/^[a-zA-Z0-9_-]{1,100}$/;
function fail(message,status=400){const e=new Error(message);e.status=status;throw e}
function keys(value,allowed){if(!value||typeof value!=='object'||Array.isArray(value)||Object.keys(value).some(k=>!allowed.includes(k)))fail('Invalid entity fields')}
function validateEntity(collection,e,id){if(e===null)return;if(collection==='items'){keys(e,['id','pid','x','y','r','color']);if(e.id!==id||!PIDS.has(e.pid)||![e.x,e.y,e.r].every(Number.isFinite)||Math.abs(e.x)>20000||Math.abs(e.y)>20000||![0,90,180,270].includes(e.r)||!/^#[0-9a-f]{6}$/i.test(e.color))fail('Invalid furniture')}else{keys(e,['id','surface','kind','w','h','u','v']);let s=SURFACES[e.surface];if(e.id!==id||!s||!['art','mirror','shelf','lamp'].includes(e.kind)||![e.w,e.h,e.u,e.v].every(Number.isFinite)||e.w<50||e.h<50||e.w>s.length||e.h>2360||e.u<e.w/2-.1||e.u>s.length-e.w/2+.1||e.v<e.h/2-.1||e.v>2360-e.h/2+.1)fail('Invalid wall decoration')}}
function validateOps(body){if(!body||!ID.test(body.requestId)||!Array.isArray(body.ops)||body.ops.length>900)fail('Invalid patch');let seen=new Set();for(let o of body.ops){keys(o,['collection','id','before','after']);if(!['items','decorations'].includes(o.collection)||!ID.test(o.id)||!('before'in o)||!('after'in o))fail('Invalid operation');let k=o.collection+o.id;if(seen.has(k))fail('Duplicate operation');seen.add(k);validateEntity(o.collection,o.before,o.id);validateEntity(o.collection,o.after,o.id)}}
const cors={'Access-Control-Allow-Origin':'*','Access-Control-Allow-Methods':'GET,POST,OPTIONS','Access-Control-Allow-Headers':'Content-Type','Cache-Control':'no-store','Content-Type':'application/json; charset=utf-8','X-Content-Type-Options':'nosniff'};
function json(data,status=200){return new Response(JSON.stringify(data),{status,headers:cors})}
function publicState(d){return {revision:d.revision,updatedAt:d.updatedAt,layout:d.layout}}
async function read(bucket){let obj=await bucket.get(KEY);if(obj)return {data:await obj.json(),etag:obj.etag};return {data:{revision:0,updatedAt:null,layout:initialLayout(),receipts:[],history:[]},etag:null}}
async function readBody(request){if(Number(request.headers.get('content-length')||0)>MAX_BYTES)fail('Request too large',413);if(!request.headers.get('content-type')?.startsWith('application/json'))fail('JSON required',415);let reader=request.body?.getReader(),chunks=[],size=0;if(!reader)fail('Empty request');while(true){let {done,value}=await reader.read();if(done)break;size+=value.byteLength;if(size>MAX_BYTES){await reader.cancel();fail('Request too large',413)}chunks.push(value)}let all=new Uint8Array(size),offset=0;for(let c of chunks){all.set(c,offset);offset+=c.length}try{return JSON.parse(new TextDecoder().decode(all))}catch{fail('Invalid JSON')}}
export default {async fetch(request,env){try{const url=new URL(request.url);if(request.method==='OPTIONS')return new Response(null,{status:204,headers:cors});if(url.pathname==='/health')return json({ok:!!env.BUCKET,service:'qiju-global-layout'});if(!env.BUCKET)fail('Storage unavailable',503);if(request.method==='GET'&&url.pathname==='/api/layout'){return json(publicState((await read(env.BUCKET)).data))}if(request.method==='GET'&&url.pathname==='/api/history'){const {data}=await read(env.BUCKET);return json({revisions:data.history.map(x=>({revision:x.revision,updatedAt:x.updatedAt}))})}if(request.method==='GET'&&/^\/api\/history\/\d+$/.test(url.pathname)){const {data}=await read(env.BUCKET),rev=Number(url.pathname.split('/').pop()),old=data.history.find(x=>x.revision===rev);return old?json(old):json({error:'Revision not found'},404)}
if(request.method==='POST'&&url.pathname==='/api/layout'){const body=await readBody(request);validateOps(body);for(let attempt=0;attempt<6;attempt++){const {data,etag}=await read(env.BUCKET);if(data.receipts.includes(body.requestId))return json(publicState(data));const result=mergePatch(data.layout,body.ops);if(result.conflicts.length)return json({...publicState(data),error:'conflict',conflicts:result.conflicts.map(o=>({collection:o.collection,id:o.id}))},409);if(result.layout.items.length>300||result.layout.decorations.length>150)fail('Layout capacity exceeded',422);if(equal(result.layout,data.layout))return json(publicState(data));const next={revision:data.revision+1,updatedAt:new Date().toISOString(),layout:result.layout,receipts:[...data.receipts,body.requestId].slice(-40),history:[...data.history,publicState(data)].slice(-10)};const written=await env.BUCKET.put(KEY,JSON.stringify(next),{onlyIf:new Headers(etag?{'If-Match':'"'+etag+'"'}:{'If-None-Match':'*'}),httpMetadata:{contentType:'application/json'}});if(written)return json(publicState(next))}return json({error:'Busy, retry shortly'},503)}return json({error:'Not found'},404)}catch(e){return json({error:e.status?e.message:'Storage request failed'},e.status||503)}}};
